#include "config.hpp"
#include <algorithm>
#include <cctype>
#include <stdexcept>

namespace {
	std::string lower(std::string text)
	{
		std::transform(text.begin(), text.end(), text.begin(), [](unsigned char c) { return char(std::tolower(c)); });
		return text;
	}

	bool boolean(std::string const& key, std::string const& value)
	{
		auto text = lower(value);
		if ((text == "true") || (text == "yes") || (text == "on") || (text == "1")) {
			return true;
		} else if ((text == "false") || (text == "no") || (text == "off") || (text == "0")) {
			return false;
		}
		throw std::runtime_error("'" + key + "' is true or false, not '" + value + "'.");
	}
} // namespace

blitz::tidy::mode blitz::tidy::config::mode_of(std::string const& rule) const
{
	if (auto it = rules.find(rule); it != rules.end()) {
		return it->second;
	}
	auto const* info = find_rule(rule);
	if (everything) {
		// "default" can not make a rule fix what it can not fix.
		return ((*everything == mode::FIX) && info && !info->fixable) ? mode::REPORT : *everything;
	}
	return info ? info->default_mode : mode::OFF;
}

void blitz::tidy::config::apply(std::vector<std::pair<std::string, std::string>> const& settings)
{
	for (auto const& [name, value] : settings) {
		std::string key = lower(name);
		std::replace(key.begin(), key.end(), '_', '-');
		key = canonical_rule(key);
		if ((key == "type-notation") || (key == "expand-short-to-long-notation") || (key == "short-type-notation")) {
			// The last two are the rules this setting replaces: on is long, off is keep.
			auto text = lower(value);
			if ((text == "long") || (text == "fix") || (text == "true")) {
				type_notation = notation::long_form;
			} else if (text == "short") {
				if (key != "type-notation") {
					throw std::runtime_error("'" + value + "' is not off or fix (" + key + "), use type-notation=short|long|keep.");
				}
				type_notation = notation::short_form;
			} else if ((text == "keep") || (text == "off") || (text == "false") || (text == "report")) {
				type_notation = notation::keep;
			} else {
				throw std::runtime_error("'" + value + "' is not keep, short or long (type-notation).");
			}
		} else if (key == "unsafe") {
			unsafe = boolean(key, value);
		} else if (key == "max-passes") {
			try {
				max_passes = std::stoi(value);
			} catch (...) {
				max_passes = 0;
			}
			if (max_passes < 1) {
				throw std::runtime_error("'max_passes' is a number above 0, not '" + value + "'.");
			}
		} else if (key == "userlibs-dir") {
			userlibs_dir = value;
		} else if (key == "default") {
			mode m;
			if (!parse_mode(lower(value), m)) {
				throw std::runtime_error("'" + value + "' is not off, report or fix (default).");
			}
			everything = m;
		} else {
			auto const* info = find_rule(key);
			if (!info) {
				throw std::runtime_error("There is no setting or rule '" + name + "', see --rules.");
			}
			mode m;
			auto text = lower(value);
			if (text == "true") {
				text = "fix";
			} else if (text == "false") {
				text = "off";
			}
			if (!parse_mode(text, m)) {
				throw std::runtime_error("'" + value + "' is not off, report or fix (" + key + ").");
			}
			if ((m == mode::FIX) && !info->fixable) {
				throw std::runtime_error("The rule '" + key + "' can only be reported, there is nothing to fix.");
			}
			rules[key] = m;
		}
	}
}
